"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[317],{5784:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","label":"Juadz","href":"/juadz/docs/intro","docId":"intro","unlisted":false},{"type":"category","label":"Guides","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Getting Started","href":"/juadz/docs/tutorial/getting-started","docId":"tutorial/getting-started","unlisted":false},{"type":"link","label":"Concepts and Request Flow","href":"/juadz/docs/tutorial/concepts","docId":"tutorial/concepts","unlisted":false},{"type":"link","label":"Resource Schemas","href":"/juadz/docs/tutorial/schema","docId":"tutorial/schema","unlisted":false},{"type":"link","label":"Data Repositories","href":"/juadz/docs/tutorial/data-repository","docId":"tutorial/data-repository","unlisted":false},{"type":"link","label":"Resources","href":"/juadz/docs/tutorial/resource","docId":"tutorial/resource","unlisted":false},{"type":"link","label":"Routing and List Queries","href":"/juadz/docs/tutorial/routing","docId":"tutorial/routing","unlisted":false},{"type":"link","label":"Authentication and Permissions","href":"/juadz/docs/tutorial/authentication","docId":"tutorial/authentication","unlisted":false},{"type":"link","label":"Resource Hooks","href":"/juadz/docs/tutorial/hooks","docId":"tutorial/hooks","unlisted":false},{"type":"link","label":"Implement a Custom Data Provider","href":"/juadz/docs/tutorial/custom-data-provider","docId":"tutorial/custom-data-provider","unlisted":false},{"type":"link","label":"Use Juadz with Another Server","href":"/juadz/docs/tutorial/other-servers","docId":"tutorial/other-servers","unlisted":false}],"href":"/juadz/docs/category/guides"}]},"docs":{"intro":{"id":"intro","title":"Juadz","description":"Juadz is a TypeScript toolkit for building CRUD APIs from Zod schemas and repository providers. It connects request validation, field-level access rules, database adapters, authentication hooks, and Fastify routes without hiding the underlying server or database.","sidebar":"tutorialSidebar"},"tutorial/authentication":{"id":"tutorial/authentication","title":"Authentication and Permissions","description":"Authentication methods are supplied to @juadz/fastify as an IAuthProvider map. Each method verifies a request and returns an actor with a permissions array, or returns null when that method does not authenticate the request.","sidebar":"tutorialSidebar"},"tutorial/concepts":{"id":"tutorial/concepts","title":"Concepts and Request Flow","description":"Juadz is organized around four pieces: a Zod schema, a data provider, a Resource, and an HTTP integration. You can use the ready-made Knex and Mongo providers or implement the provider interface for your own persistence layer.","sidebar":"tutorialSidebar"},"tutorial/custom-data-provider":{"id":"tutorial/custom-data-provider","title":"Implement a Custom Data Provider","description":"A provider is the storage adapter between a Resource and your database or service. Implement IDataRepositoryProvider from @juadz/core, then pass the provider to new Resource(provider). The provider must define name and schema; each CRUD method is optional. Only implemented methods generate their corresponding standard routes.","sidebar":"tutorialSidebar"},"tutorial/data-repository":{"id":"tutorial/data-repository","title":"Data Repositories","description":"A data provider connects a resource to storage. Juadz calls only the operations implemented by the provider; those operations determine which standard routes are generated.","sidebar":"tutorialSidebar"},"tutorial/getting-started":{"id":"tutorial/getting-started","title":"Getting Started","description":"Create a starter project with Node.js and npm installed:","sidebar":"tutorialSidebar"},"tutorial/hooks":{"id":"tutorial/hooks","title":"Resource Hooks","description":"Hooks let you transform resource data around provider operations. Register hooks on a resource with addHook; each callback receives the current value and a context object.","sidebar":"tutorialSidebar"},"tutorial/other-servers":{"id":"tutorial/other-servers","title":"Use Juadz with Another Server","description":"@juadz/core does not depend on Fastify. A Resource exposes endpoint definitions through generateEndpoints(). Each endpoint includes a method, path, optional Zod schemas and an async handler. An HTTP adapter maps your server\'s request and response types to Juadz\'s ResourceHandlerParams and IHttpJsonResponse contracts.","sidebar":"tutorialSidebar"},"tutorial/resource":{"id":"tutorial/resource","title":"Resources","description":"A Resource combines a repository provider with a resource name and exposes the supported operations as HTTP endpoints when registered with the Fastify integration.","sidebar":"tutorialSidebar"},"tutorial/routing":{"id":"tutorial/routing","title":"Routing and List Queries","description":"The Fastify integration generates routes from the operations implemented by each provider. By default, a resource named users has:","sidebar":"tutorialSidebar"},"tutorial/schema":{"id":"tutorial/schema","title":"Resource Schemas","description":"Juadz uses Zod schemas to validate resource input and output. The schema must be a Zod object with an id field; choose the ID type that matches your provider.","sidebar":"tutorialSidebar"}}}}')}}]);